-- =====================================================================
-- V1 nutrition — READ-ONLY post-deployment verification. Run after
-- 20261029120000_v1_nutrition_tracking_engagement.sql (as postgres, or in
-- the SQL Editor of the target project). Changes nothing.
--
-- The nutrition migration replaces public.containment_violations() with
-- the Phase 1C monitor plus nine reviewed entries (generated by
-- supabase/tools/generate_nutrition_monitor.py). After it, Phase 1C's own
-- postdeploy_verify_readonly.sql reports a different monitor fingerprint
-- by design; use this file instead. NUTRITION_MONITOR_MD5 must equal a
-- clean application of the migration (run_v1_nutrition.sh checks it).
-- =====================================================================
with
expected(monitor_md5) as (values ('NUTRITION_MONITOR_MD5:1bbbc1b29865c5700a680b3711ef84e3')),
mon as (
  select md5(p.prosrc) as body_md5, p.prosecdef, p.proconfig, pg_get_userbyid(p.proowner) as owner,
         has_function_privilege('anon', p.oid, 'EXECUTE') or has_function_privilege('authenticated', p.oid, 'EXECUTE') as client_exec
    from pg_proc p where p.oid = to_regprocedure('public.containment_violations()')
),
checks(check_name, ok, detail) as (
  select 'monitor_fingerprint_matches_review',
         coalesce((select m.body_md5 = split_part(e.monitor_md5, ':', 2) from mon m, expected e), false),
         coalesce((select 'md5(prosrc)=' || body_md5 from mon), 'missing')
  union all
  select 'monitor_invoker_fixed_search_path_owner_postgres_no_client_execute',
         coalesce((select not prosecdef and proconfig = array['search_path=""'] and owner = 'postgres' and not client_exec from mon), false),
         'definer/config/owner/client execute'
  union all
  select 'nutrition_objects_present',
         to_regclass('public.nutrition_log_entries') is not null and to_regclass('public.notification_deliveries') is not null
           and to_regprocedure('public.nutrition_plan_notifications(timestamp with time zone)') is not null,
         'tables and planner'
  union all
  select 'server_only_functions_not_client_executable',
         not exists (select 1 from unnest(array['public.nutrition_plan_notifications(timestamp with time zone)',
                       'public.nutrition_claim_deliveries(integer)', 'public.nutrition_record_delivery(bigint,jsonb,text)',
                       'public.nutrition_record_receipts(jsonb)']) f
                      where has_function_privilege('authenticated', f::regprocedure, 'EXECUTE')
                         or has_function_privilege('anon', f::regprocedure, 'EXECUTE')),
         'planner and dispatch functions'
  union all
  select 'containment_violations_zero_rows', r.n = '0', 'rows=' || r.n
    from (select case when coalesce((select m.body_md5 = split_part(e.monitor_md5, ':', 2) from mon m, expected e), false)
                      then (xpath('/row/n/text()', query_to_xml(
                              'select count(*) as n from public.containment_violations() where category in (''drift'', ''containment'')',
                              false, true, '')))[1]::text
                      else 'not run (monitor not verified)' end as n) r
)
select jsonb_pretty(jsonb_build_object(
  'generated_at', now(),
  'all_required_checks_ok', coalesce((select bool_and(coalesce(ok, false)) from checks), false),
  'checks', (select jsonb_agg(jsonb_build_object('check', check_name, 'ok', coalesce(ok, false), 'detail', detail)) from checks)
)) as v1_nutrition_postdeploy;
